/* * JProgressMemory.java  * Created on 14 juillet 2007, 03:27  * To change this template, choose Tools | Template Manager  and open the template in the editor. */package net.sf.jiga.xtended.ui;import java.awt.AlphaComposite;import java.awt.Color;import java.awt.Composite;import java.awt.Dimension;import java.awt.Font;import java.awt.GradientPaint;import java.awt.Graphics;import java.awt.Graphics2D;import java.awt.Image;import java.awt.MediaTracker;import java.awt.Paint;import java.awt.Point;import java.awt.Rectangle;import java.awt.Shape;import java.awt.geom.AffineTransform;import java.util.Collections;import java.util.HashMap;import java.util.Map;import javax.swing.BoundedRangeModel;import javax.swing.JProgressBar;import net.sf.jiga.xtended.impl.Sprite;import net.sf.jiga.xtended.impl.SpriteIO;import net.sf.jiga.xtended.impl.system.SfMediaTracker;/** * * JProgressMemory extends the JProgressBar class to add new look and feel * and provide a 3-in-one JProgressBar instance. * * * @author www.b23prodtm.info */public class JProgressMemory extends JProgressBar implements OpaqueComponent, PaintStyle {        long hash = System.nanoTime();        public int hashCode() {                return (int) hash;        }        public boolean equals(Object o) {                return o == null ? false : o.hashCode() == hashCode();        }        /**         * the memory initialized JProgressBar instance         */        JProgressBar memory_init;        /**         * the memory committed JProgressBar instance         */        JProgressBar memory_committed;        /**         * creates a new instance         */        public JProgressMemory() {                super();                memory_init = new JProgressBar();                memory_committed = new JProgressBar();                memory_init.setDoubleBuffered(true);                memory_committed.setDoubleBuffered(true);        }        /**         * creates a new instance         *         * @param model the BoundedRangeModel instance to use         * @see JProgressBar#JProgressBar(BoundedRangeModel)         */        public JProgressMemory(BoundedRangeModel model) {                super(model);                memory_init = new JProgressBar(model);                memory_committed = new JProgressBar(model);                memory_init.setDoubleBuffered(true);                memory_committed.setDoubleBuffered(true);        }        /**         * creates a new instance         *         * @param min the minimum value         * @param max the maximum value         * @see JProgressBar#JProgressBar(int, int)         */        public JProgressMemory(int min, int max) {                super(min, max);                memory_init = new JProgressBar(min, max);                memory_committed = new JProgressBar(min, max);                memory_init.setDoubleBuffered(true);                memory_committed.setDoubleBuffered(true);        }        /**         * creates a new instance         *         * @param orient the orientation of the JProgressBar instance         * @param min the minimum value         * @param max the maximum value         * @see JProgressBar#JProgressBar(int, int, int)         */        public JProgressMemory(int orient, int min, int max) {                super(orient, min, max);                memory_init = new JProgressBar(orient, min, max);                memory_committed = new JProgressBar(orient, min, max);                memory_init.setDoubleBuffered(true);                memory_committed.setDoubleBuffered(true);        }        /**         * creates new instance         *         * @param orient the orientation of the JProgressBar instance         * @see JProgressBar#JProgressBar(int)         */        public JProgressMemory(int orient) {                super(orient);                memory_init = new JProgressBar(orient);                memory_committed = new JProgressBar(orient);                memory_init.setDoubleBuffered(true);                memory_committed.setDoubleBuffered(true);        }        /**         * arc value for rounded rectangles         */        private final int arc = 10;        public int style = STYLE_FLAT;        private GradientPaint addGradient(JProgressBar jpb, Graphics2D g2, Color color1, Color color2, String name) {                GradientPaint gradient = null;                Rectangle bounds = jpb.getBounds();                switch (jpb.getOrientation()) {                        case HORIZONTAL:                                if (gradients.get("layer" + name + "-H") instanceof Map) {                                        if (gradients.get("layer" + name + "-H").get(jpb.getSize()) instanceof Paint) {                                                gradient = gradients.get("layer" + name + "-H").get(jpb.getSize());                                                break;                                        }                                }                                if (style == STYLE_GLOW) {                                        gradients.put("layer" + name + "-H", Collections.singletonMap(jpb.getSize(), gradient = new GradientPaint((float) bounds.x, (float) bounds.y, color1, (float) bounds.x, bounds.y + (float) bounds.height / 2.0f, color2, true)));                                }                                if (style == STYLE_FLAT) {                                        gradients.put("layer" + name + "-H", Collections.singletonMap(jpb.getSize(), gradient = new GradientPaint((float) bounds.x, (float) bounds.y, color1, bounds.x + bounds.width, bounds.y + (float) bounds.height / 2.0f, color2, true)));                                }                                break;                        case VERTICAL:                                if (gradients.get("layer" + name + "-V") instanceof Map) {                                        if (gradients.get("layer" + name + "-V").get(jpb.getSize()) instanceof Paint) {                                                gradient = gradients.get("layer" + name + "-V").get(jpb.getSize());                                                break;                                        }                                }                                if (style == STYLE_GLOW) {                                        gradients.put("layer" + name + "-V", Collections.singletonMap(jpb.getSize(), gradient = new GradientPaint((float) bounds.x, (float) bounds.y, color1, bounds.x + (float) bounds.width / 2.0f, bounds.y, color2, true)));                                }                                if (style == STYLE_FLAT) {                                        gradients.put("layer" + name + "-V", Collections.singletonMap(jpb.getSize(), gradient = new GradientPaint((float) bounds.x, (float) bounds.y, color1, bounds.x + (float) bounds.width / 2.0f, bounds.y + bounds.height, color2, true)));                                }                                break;                        default:                                break;                }                return gradient;        }        /**         * draws the specified JProgressBar on the specified Graphics instance         *         * @param g2 the Graphics instance to draw onto         * @param jpb the JProgressBar the paint         * @param color the front-color         * @param name the name for the JProgressBar         */        public void draw(Graphics2D g2, JProgressBar jpb, Color color, String name) {                Rectangle bounds = jpb.getBounds();                Color c = g2.getColor();                g2.setColor(color);                GradientPaint gradient = addGradient(jpb, g2, g2.getBackground(), g2.getColor(), name);                Paint paint = g2.getPaint();                g2.setPaint(gradient);                Font font = new Font("Arial", Font.ITALIC, 9);                String string = name;                Font f = g2.getFont();                g2.setFont(font);                int val = 0;                float max = jpb.isIndeterminate() ? 100 : jpb.getMaximum();                float value = jpb.isIndeterminate() ? indeterminate * max : jpb.getValue();                switch (jpb.getOrientation()) {                        case HORIZONTAL:                                val = (int) (value / max * (float) bounds.width);                                g2.fillRoundRect(bounds.x + (jpb.isIndeterminate() ? val - (int) ((float) bounds.width / 5f) : 0), bounds.y, jpb.isIndeterminate() ? (int) ((float) bounds.width / 5f) : val, bounds.height, arc, arc);                                g2.setColor(Color.BLACK);                                g2.drawString(string, bounds.x + val - g2.getFontMetrics(font).stringWidth(string), bounds.y + bounds.height - 5);                                break;                        case VERTICAL:                                val = (int) (value / max * (float) bounds.height);                                g2.fillRoundRect(bounds.x, bounds.y + bounds.height - val, bounds.width, jpb.isIndeterminate() ? (int) ((float) bounds.height / 5f) : val, arc, arc);                                g2.setColor(Color.BLACK);                                AffineTransform tx = g2.getTransform();                                Point str = new Point((int) (bounds.x + (float) (bounds.width - g2.getFontMetrics(font).getHeight()) / 2f), bounds.y + bounds.height - val);                                g2.rotate(-Math.PI * 3.0 / 2.0, str.getX(), str.getY());                                g2.drawString(string, str.x, str.y);                                g2.setTransform(tx);                                break;                        default:                                break;                }                g2.setFont(f);                g2.setColor(c);                g2.setPaint(paint);        }        /**         * the glow effect value         */        private static float glow = .0f;        /**         * the indeterminate state value         */        private static float indeterminate = .0f;        /**         * the timestamp         */        private static long t = 0;        /**         * the angular value         */        private static float theta = 0f;        /**         * the glow effect         */        private static void _glow() {                if (t == 0) {                        t = System.currentTimeMillis();                }                long now = System.currentTimeMillis();                theta += ((float) (now - t) / 1000f) * (float) Math.PI / 8f;                theta = theta % (2f * (float) Math.PI);                glow = Math.abs((float) Math.sin(theta));                indeterminate = Math.abs((float) Math.cos(theta));                t = now;        }        /**         * the 3 JProgressBar's         */        String initBar, committedBar, overallBar;        /**         * sets up the labels for each of the 3 JProgressBar's         *         * @param initBar the first bottom-initialized JProgressBar label         * @param committedBar the second committed-memory JProgressBar label         * @param overallBar the last top-most overlapping JProgressBar label         */        public void setLabels(String initBar, String committedBar, String overallBar) {                this.initBar = initBar;                this.committedBar = committedBar;                this.overallBar = overallBar;        }        /**         * the offscreen buffer         */        Sprite offscreen = null;        /**         * finalization         *         * @see JProgressBar#finalize()         */        protected void finalize() throws Throwable {                super.finalize();        }        private void updateSubJPB() {                Rectangle bounds = getBounds();                memory_committed.setBounds(bounds);                memory_init.setBounds(bounds);                memory_init.setStringPainted(false);                memory_committed.setStringPainted(false);                memory_init.setOrientation(getOrientation());                memory_committed.setOrientation(getOrientation());        }        private boolean opaque = false;        private Color colors[] = new Color[]{Color.GRAY, Color.WHITE, Color.LIGHT_GRAY};        public void setColors(Color overallheap, Color initialized, Color committed) {                colors = new Color[]{overallheap, initialized, committed};        }        public boolean isOpaque() {                return opaque;        }        public void setOpaque(boolean b) {                super.setOpaque(b);                opaque = b;        }        private Map<String, Map<Dimension, GradientPaint>> gradients = Collections.synchronizedMap(new HashMap<String, Map<Dimension, GradientPaint>>());        /**         * paints the whole instance on the specified Graphics instance         *         * @param pg the Graphics instance ot paint the buffer onto         */        protected void paintComponent(Graphics pg) {                if (style == STYLE_FLAT) {                        setBorderPainted(false);                }                Graphics2D g = Sprite.wrapRendering(pg);                Shape clip = g.getClip();                Rectangle bounds = getBounds();                updateSubJPB();                g.translate(-bounds.x, -bounds.y);                g.clip(bounds);                if (isOpaque()) {                        Color c = g.getColor();                        g.setColor(getBackground());                        g.fillRoundRect(bounds.x, bounds.y, bounds.width, bounds.height, arc, arc);                        g.setColor(c);                }                if (offscreen == null) {                        offscreen = /*!Sprite._isTrueVolatile() ? */ new Sprite(SpriteIO.createBufferedImage(getSize(), Sprite.DEFAULT_TYPE), "image/x-png", getSize())/* : new Sprite(Sprite.createVolatileImage(getSize()), "image/x-png", getSize())*/;                        offscreen.setMt(new SfMediaTracker(this), this);                }                offscreen.setBounds(bounds);                if (isIndeterminate()) {                        _glow();                }                if (initBar == null) {                        initBar = "i";                }                if (committedBar == null) {                        committedBar = "c";                }                if (overallBar == null) {                        overallBar = "*";                }                int pty = Thread.currentThread().getPriority();                Thread.currentThread().setPriority(Thread.MAX_PRIORITY);                offscreen.runValidate();                offscreen.clearImageGraphics();                Image off = offscreen.getImage(this);                Graphics dataG = Sprite._createImageGraphics(off);                if (dataG == null) {                        return;                }                Graphics2D g2 = Sprite.wrapRendering(dataG);                g2.setClip(0, 0, offscreen.getWidth(), offscreen.getHeight());                g2.translate(-bounds.x, -bounds.y);                Composite cps = g2.getComposite();                Color c = g2.getColor();                g2.setBackground(Color.WHITE);                g2.fillRoundRect(bounds.x, bounds.y, bounds.width, bounds.height, arc, arc);                g2.setColor(Color.ORANGE);                GradientPaint gradient = addGradient(this, g2, g2.getBackground(), g2.getColor(), "0");                final float glow = isIndeterminate() ? JProgressMemory.glow : 1f;                g2.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, glow));                Paint paint = g2.getPaint();                g2.setPaint(gradient);                g2.fillRoundRect(bounds.x, bounds.y, bounds.width, bounds.height, arc, arc);                g2.setPaint(paint);                draw(g2, this, colors[0], overallBar);                g2.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, Math.max(0f, glow - 0.3f)));                draw(g2, memory_init, colors[1], initBar);                draw(g2, memory_committed, colors[2], committedBar);                g2.setComposite(cps);                g2.setColor(Color.BLACK);                Font font = new Font("Arial", Font.ITALIC, 9);                String str = "max";                Font f = g2.getFont();                g2.setFont(font);                if (!isIndeterminate()) {                        switch (getOrientation()) {                                case HORIZONTAL:                                        g2.drawString(str, bounds.x + bounds.width - g2.getFontMetrics(font).stringWidth(str) - 5, bounds.y + (int) ((float) (bounds.height + g2.getFontMetrics(font).getHeight()) * .5f));                                        break;                                case VERTICAL:                                        g2.drawString(str, bounds.x + bounds.width - g2.getFontMetrics(font).stringWidth(str), bounds.y + g2.getFontMetrics(font).getHeight() + 5);                                        break;                                default:                                        break;                        }                }                g2.setFont(f);                float str_x = 0.0f;                float str_y = 0.0f;                switch (getOrientation()) {                        case HORIZONTAL:                                str_x = bounds.x + (float) (bounds.width - g2.getFontMetrics().stringWidth(getString())) / 2f;                                str_y = bounds.y + (float) (bounds.height + g2.getFontMetrics().getHeight()) / 2f;                                break;                        case VERTICAL:                                str_y = bounds.y + (float) (bounds.height - g2.getFontMetrics().stringWidth(getString())) / 2f;                                str_x = bounds.x + (float) (bounds.width - g2.getFontMetrics().getHeight()) / 2f;                                break;                        default:                                break;                }                if (isStringPainted()) {                        if (getOrientation() == VERTICAL) {                                g2.rotate(-Math.PI * 3.0 / 2.0, str_x, str_y);                                g2.drawString(getString(), str_x, str_y);                                g2.rotate(Math.PI * 3.0 / 2.0, str_x, str_y);                        } else {                                g2.drawString(getString(), str_x, str_y);                        }                }                if (isBorderPainted()) {                        g2.setColor(Color.BLACK);                        g2.drawRoundRect(bounds.x + getInsets().left, bounds.y + getInsets().top, bounds.width - getInsets().right, bounds.height - getInsets().bottom, arc, arc);                }                g2.setPaint(paint);                g2.setColor(c);                g2.dispose();                offscreen.runValidate();                offscreen.draw(this, g);                off.flush();                Thread.currentThread().setPriority(pty);                g.translate(bounds.x, bounds.y);                g.setClip(clip);        }        /**         * returns the maximum value of the "init" JProgressBar         *         * @return the maximum value of the "init" JProgressBar         * @see JProgressBar#getMaximum()         */        public int getMaximum_init() {                return memory_init.getMaximum();        }        /**         * returns the maximum value of the "committed" JProgressBar         *         * @return the maximum value of the "committed" JProgressBar         * @see JProgressBar#getMaximum()         */        public int getMaximum_committed() {                return memory_committed.getMaximum();        }        /**         * returns the value of the "init" JProgressBar         *         * @return the value of the "init" JProgressBar         * @see JProgressBar#getValue()         */        public int getValue_init() {                return memory_init.getValue();        }        /**         * returns the value of the "committed" JProgressBar         *         * @return the value of the "committed" JProgressBar         * @see JProgressBar#getValue()         */        public int getValue_committed() {                return memory_committed.getValue();        }        /**         * returns the JProgressBar "init" instance         *         * @return the JProgressBar "init" instance         */        public JProgressBar getProgress_init() {                return memory_init;        }        /**         * returns the JProgressBar "committed" instance         *         * @return the JProgressBar "committed" instance         */        public JProgressBar getProgress_committed() {                return memory_committed;        }        /**         * sets up the current value for the "init" JProgressBar         *         * @param i the "init" JProgressBar instance value         * @see JProgressBar#setValue(int)         */        public void setValue_init(int i) {                memory_init.setValue(i);        }        /**         * sets up the current value for the "committed" JProgressBar         *         * @param i the "committed" JProgressBar instance value         * @see JProgressBar#setValue(int)         *         */        public void setValue_committed(int i) {                memory_committed.setValue(i);        }        /**         * dis/enables the indeterminate mode         *         * @param newValue dis/enables the indeterminate mode         * @see JProgressBar#setIndeterminate(boolean)         */        public void setIndeterminate(boolean newValue) {                super.setIndeterminate(newValue);        }        /**         * sets up the maximum value for the "init" JProgressBar         *         * @param i the "init" JProgressBar instance maximum value         * @see JProgressBar#setMaximum(int)         */        public void setMaximum_init(int i) {                memory_init.setMaximum(i);        }        /**         * sets up the maximum value for the "committed" JProgressBar         *         * @param i the "committed" JProgressBar instance maximum value         * @see JProgressBar#setMaximum(int)         */        public void setMaximum_committed(int i) {                memory_committed.setMaximum(i);        }        /**         * sets up the orientation of this JProgressMemory instance         *         * @param orient the orientation of this JProgressMemory instance         * @see JProgressBar#HORIZONTAL         * @see JProgressBar#VERTICAL         */        public void setOrientation(int orient) {                super.setOrientation(orient);                if (memory_init != null) {                        memory_init.setOrientation(orient);                }                if (memory_committed != null) {                        memory_committed.setOrientation(orient);                }        }}